//! BR CHARACTER MATERIALS: the data side of the original compiled character materials (head / hair / body skin, eyeshadow).
//!
//! What is recovered (all from the 1.8 packages, see `br_material_gen.rs` / `fn-render/shaders/*_gen.wgsl`, generated by
//! `cargo run -p fn-dxbc-cli --release --example br_character_materials`):
//! * The skin / hair swatches (`CustomSkinColorSwatch` / `CustomHairColorSwatch`: `ColorPairs` of `ColorName` -> colour) are applied the way the engine applies them: every pair
//!   is a vector parameter override BY NAME on the part's material instance. The material graph decides what the names do: the head / hair / body materials
//!   (`CharacterShader` and its `_WhiteAO` / `_Gloss` permutations) have no parameter called `SkinToneBase`, `HairTone_*`, ... (see [`swatch_report`]), so for the BR default hero the
//!   swatches change nothing and the skin tone / hair colour come from the `Diffuse` textures. Nothing is guessed to make them visible.
//! * The base-pass pixel shader of the permutation that owns the material's shader map (`CharacterShader` = default, `CharacterShader_WhiteAO` = hair,
//!   `CharacterShader_Gloss` = body) is translated by fn-dxbc; its material constant buffer is the cooked uniform expression set evaluated with the instance chain's parameters.
//!   CHAR PREPASS (2026-10-06): so is its depth-only coverage shader (`FDepthOnlyPS`, `fn-render/shaders/char_depth_gen.wgsl`), which samples the fixed textures 8, 9, 10
//!   ([`CharSection::res_in`]).
//! * `Eyeshadow` (plain `BLEND_Modulate`, `MSM_Unlit`): the translated pixel shader, its constants (cooked defaults) and its three fixed textures, plus the vertex colour (R) painted into
//!   the head mesh.
//! * `M_Athena_InvisibleGrenades` (plain `BLEND_Masked`): every coverage shader (depth pre-pass, shadow depth, hit proxy, velocity, lightmap density) discards unconditionally.
//!
//! `__SubsurfaceProfile` = the allocation id of the chain's profile ([`subsurface_profile_id`], fn-render subsurface.rs). Not recoverable / not done: runtime-driven
//! parameters (`HitGlow`, `SuperChargedEffect`, `DissolveGradient*`, `AverageHandPosition`: defaults are used), the atmospheric-fog fade `TEXCOORD7.w` of the eyeshadow vertex
//! shader (the fog start distance is a sky actor setting; 1.0 is used, exact inside the fog start distance), the per-vertex tangents (the renderer's derivative frame is used).
use crate::br_character::{RgbaTexture, PartDef};
use crate::br_material_gen as genm;
use crate::{loader, ClipSourceDir};
use fn_ueio::props::{read_props, Ctx, PropList, PropValue};
use fn_ueio::{Package, Reader};
use std::collections::HashMap;

pub use genm::ALWAYS_DISCARD;

/// A texture that is not a material parameter. `srgb` = the texture's SRGB flag AND the graph node's sampler type is `Color` (a `LinearColor` node reads the raw values).
#[derive(Clone, Debug)]
pub struct FixedTex { pub tex: RgbaTexture, pub srgb: bool, pub address: [String; 2], pub path: String }

#[derive(Clone, Debug)]
pub struct CharSection {
    /// `head` / `hair` / `body`: the permutation whose compiled pixel shader runs.
    pub perm: &'static str,
    /// The package that owns the shader map (nearest owner in the instance chain).
    pub owner: String,
    /// The material uniform buffer (`cb3`), registers in the order of the cooked uniform expression set.
    pub cb: Vec<[f32; 4]>,
    /// Fixed texture slot 7: the super-charged flicker noise.
    pub noise: FixedTex,
    /// CHAR PREPASS (2026-10-06): fixed texture slots 8, 9, 10 of the depth-only coverage shader (`char_depth_gen.wgsl`): see [`RES_IN_TEXTURES`].
    pub res_in: [FixedTex; 3],
    pub subsurface_profile: u32,
}

#[derive(Clone, Debug)]
pub struct Eyeshadow {
    /// The material uniform buffer (`cb1`), cooked defaults.
    pub cb: Vec<[f32; 4]>,
    /// Fixed textures by texture index 0, 1, 2.
    pub tex: [FixedTex; 3],
}

/// Fixed (non-parameter) textures of the translated shaders: (texture index of the uniform expression set, object path, graph sampler type is LinearColor).
/// Evidence: index 7 of the character shaders is read with a time-scrolled UV and added to `SuperChargedFlickerBias`: `SuperChargedGlow`'s only texture sample is `UI_Faces/Noise`.
/// Eyeshadow indices 0, 1, 2 are the texture samples of `CharacterResInEffect` in graph order (T_NoisePack_01 [Color], T_Slowfield_GridSquares_01 [LinearColor],
/// ShieldPowerAnim [LinearColor]); the shader samples index 1 at UV x `texture pattern tiling` (the 3.4375 sampling scale of the cooked streaming data), index 0 at UV, index 2 as a 1-D gradient.
const NOISE_PATH: &str = "/Game/UI/UI_Faces/Noise.Noise";
const EYESHADOW_TEXTURES: [(&str, bool); 3] = [
    ("/Game/Effects/Fort_Effects/Gameplay/SmokeDustExplosions/Textures/T_NoisePack_01.T_NoisePack_01", false),
    ("/Game/Gadgets/Assets/Slow_Field/Textures/T_Slowfield_GridSquares_01.T_Slowfield_GridSquares_01", true),
    ("/Game/Packages/Fortnite_UniqueMaterials_1/Effects/ShieldPowerAnim.ShieldPowerAnim", true),
];
pub const EYESHADOW_MATERIAL: &str = "/Game/Characters/Player/Common/Eyes/Materials/Eyeshadow";
/// CHAR PREPASS (2026-10-06): texture indices 8, 9, 10 of the character shaders = `ExpressionTextureReferences[8..=10]` of `CharacterShader` (fn-fx `Material::load`):
/// T_NoisePack_01, T_Slowfield_GridSquares_01, ShieldPowerAnim. Only the depth-only coverage shader samples them (index 8 at UV, 9 at UV x `texture pattern tiling`,
/// 10 as the 1-D dissolve gradient). They are the samples of `CharacterResInEffect`, which CharacterShader and Eyeshadow both call, so the graph sampler types are the
/// eyeshadow's.
const RES_IN_TEXTURES: [(&str, bool); 3] = EYESHADOW_TEXTURES;

fn export_props(pkg: &Package, idx: usize) -> Result<PropList, String> {
    let (start, end) = pkg.export_range(idx);
    read_props(&mut Reader::at(&pkg.data[..end], start), &Ctx { names: &pkg.names, file_version: pkg.summary.file_version }).map_err(|e| e.to_string())
}

fn obj_path(pkg: &Package, v: &PropValue) -> Option<String> {
    match v { PropValue::Object(i) if *i < 0 => Some(pkg.import_path(*i)), PropValue::Str(s) if s.starts_with("/Game/") => Some(s.clone()), _ => None }
}

fn param_name(f: &PropList) -> Option<String> {
    f.text("ParameterName").or_else(|| f.fields("ParameterInfo").and_then(|i| i.text("Name"))).map(str::to_owned)
}

/// Parameters of a material instance chain, leaf first wins (the engine looks parameters up leaf -> parent -> ... and falls back to the root material's expression default,
/// which the uniform expression recipe carries as the default value).
#[derive(Clone, Debug, Default)]
pub struct ChainParams {
    /// Long package paths, leaf first (instances, then the root material).
    pub packages: Vec<String>,
    pub vectors: HashMap<String, [f32; 4]>,
    pub scalars: HashMap<String, f32>,
    pub subsurface_profile: Option<String>,
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct SubsurfaceProfileSettings { pub scatter_radius: f32, pub subsurface_color: [f32; 3], pub falloff_color: [f32; 3] }
impl Default for SubsurfaceProfileSettings {
    fn default() -> Self { SubsurfaceProfileSettings { scatter_radius: 1.2, subsurface_color: [0.48, 0.41, 0.28], falloff_color: [1.0, 0.37, 0.3] } }
}
static SSS_PROFILES: std::sync::Mutex<Vec<(String, SubsurfaceProfileSettings)>> = std::sync::Mutex::new(Vec::new());
pub fn subsurface_profiles() -> Vec<(String, SubsurfaceProfileSettings)> {
    let mut g = SSS_PROFILES.lock().unwrap_or_else(|p| p.into_inner());
    if g.is_empty() { g.push((String::new(), SubsurfaceProfileSettings::default())); }
    g.clone()
}
pub fn read_subsurface_profile(src: &ClipSourceDir, path: &str) -> Result<SubsurfaceProfileSettings, String> {
    let long = path.split_once('.').map_or(path, |s| s.0);
    let pkg = loader::package(src, long)?;
    let idx = (0..pkg.exports.len()).find(|&i| pkg.export_class(i) == "SubsurfaceProfile").ok_or_else(|| format!("{path}: no SubsurfaceProfile export"))?;
    let props = export_props(&pkg, idx)?;
    let mut out = SubsurfaceProfileSettings::default();
    if let Some(f) = props.fields("Settings") {
        if let Some(r) = f.float("ScatterRadius") { out.scatter_radius = r as f32; }
        if let Some(PropValue::Vec4(c)) = f.get("SubsurfaceColor") { out.subsurface_color = [c[0], c[1], c[2]]; }
        if let Some(PropValue::Vec4(c)) = f.get("FalloffColor") { out.falloff_color = [c[0], c[1], c[2]]; }
    }
    Ok(out)
}
pub fn subsurface_profile_id(src: &ClipSourceDir, path: Option<&str>) -> Result<u32, String> {
    let Some(path) = path else { return Ok(0) };
    {
        let mut g = SSS_PROFILES.lock().unwrap_or_else(|p| p.into_inner());
        if g.is_empty() { g.push((String::new(), SubsurfaceProfileSettings::default())); }
        if let Some(i) = g.iter().position(|(p, _)| p == path) { return Ok(i as u32); }
    }
    let settings = read_subsurface_profile(src, path)?;
    let mut g = SSS_PROFILES.lock().unwrap_or_else(|p| p.into_inner());
    if let Some(i) = g.iter().position(|(p, _)| p == path) { return Ok(i as u32); }
    g.push((path.to_owned(), settings));
    Ok(g.len() as u32 - 1)
}

pub fn chain_params(src: &ClipSourceDir, material: &str) -> Result<ChainParams, String> {
    let mut out = ChainParams::default();
    let mut profile_decided = false;
    let mut cur = Some(material.to_owned());
    while let Some(path) = cur.take() {
        if out.packages.len() > 16 { return Err(format!("{material}: material parent chain too deep")); }
        let (long, object) = path.split_once('.').ok_or_else(|| format!("{path}: material needs a full object path"))?;
        let pkg = loader::package(src, long)?;
        let idx = pkg.exports.iter().position(|e| e.object_name == object).ok_or_else(|| format!("{path}: missing material export"))?;
        out.packages.push(long.to_owned());
        let props = export_props(&pkg, idx)?;
        if pkg.export_class(idx) != "MaterialInstanceConstant" {
            if !profile_decided { out.subsurface_profile = props.get("SubsurfaceProfile").and_then(|v| obj_path(&pkg, v)); }
            break;
        }
        if !profile_decided && props.bool("bOverrideSubsurfaceProfile") == Some(true) { out.subsurface_profile = props.get("SubsurfaceProfile").and_then(|v| obj_path(&pkg, v)); profile_decided = true; }
        for v in props.array("ScalarParameterValues").map(|a| a.as_slice()).unwrap_or(&[]) {
            let Some(f) = v.as_fields() else { continue };
            if let (Some(n), Some(x)) = (param_name(f), f.float("ParameterValue")) { out.scalars.entry(n).or_insert(x as f32); }
        }
        for v in props.array("VectorParameterValues").map(|a| a.as_slice()).unwrap_or(&[]) {
            let Some(f) = v.as_fields() else { continue };
            if let (Some(n), Some(PropValue::Vec4(c))) = (param_name(f), f.get("ParameterValue")) { out.vectors.entry(n).or_insert(*c); }
        }
        cur = props.get("Parent").and_then(|v| obj_path(&pkg, v));
    }
    Ok(out)
}

/// `ColorPairs` of a `CustomSkinColorSwatch` / `CustomHairColorSwatch` asset: (ColorName, ColorValue).
pub fn read_swatch(src: &ClipSourceDir, swatch: &str) -> Result<Vec<(String, [f32; 4])>, String> {
    let long = swatch.split_once('.').map_or(swatch, |s| s.0);
    let pkg = loader::package(src, long)?;
    let idx = (0..pkg.exports.len()).find(|&i| pkg.export_class(i).ends_with("ColorSwatch")).ok_or_else(|| format!("{swatch}: no colour swatch export"))?;
    let props = export_props(&pkg, idx)?;
    let mut out = vec![];
    for v in props.array("ColorPairs").map(|a| a.as_slice()).unwrap_or(&[]) {
        let f = v.as_fields().ok_or("bad ColorPairs entry")?;
        let name = f.text("ColorName").ok_or("ColorPair without a name")?;
        let Some(PropValue::Vec4(c)) = f.get("ColorValue") else { return Err(format!("{swatch}: ColorPair {name} has no colour")) };
        out.push((name.to_owned(), *c));
    }
    Ok(out)
}

pub const DISSOLVE_PARAMS: [&str; 5] = ["DissolveGradientBaseLocation", "DissolveGradientDirectionalVector", "DissolveGradientDistance", "DissolveGradientPercentage", "FirstSpawnPassComplete"];

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct ParamPatch { pub reg: usize, pub comp: usize, pub param: usize, pub src: usize, pub scale: f32, pub default: f32 }

fn recipe(perm: &str, p: &dyn Fn(&str, [f32; 4]) -> [f32; 4]) -> Option<Vec<[f32; 4]>> {
    match perm { "head" => Some(genm::head_cb(p).to_vec()), "hair" => Some(genm::hair_cb(p).to_vec()), "body" => Some(genm::body_cb(p).to_vec()), _ => None }
}

pub fn param_patches(perm: &str, names: &[&str]) -> Vec<ParamPatch> {
    let mut out = vec![];
    let Some(c0) = recipe(perm, &|_, d| d) else { return out };
    for (pi, name) in names.iter().enumerate() {
        for src in 0..4 {
            let def = std::cell::Cell::new(None);
            let probe = |k: f32| recipe(perm, &|n: &str, d: [f32; 4]| if n == *name { def.set(Some(d[src])); let mut v = d; v[src] += k; v } else { d }).unwrap_or_default();
            let (c1, c2) = (probe(1.), probe(2.));
            let Some(d) = def.get() else { continue };
            for reg in 0..c0.len() { for comp in 0..4 {
                let s1 = c1[reg][comp] - c0[reg][comp];
                if s1 == 0. { continue; }
                let s2 = c2[reg][comp] - c0[reg][comp];
                if (s2 - 2. * s1).abs() > 1e-4 * s1.abs().max(1.) { continue; }
                out.push(ParamPatch { reg, comp, param: pi, src, scale: s1, default: d });
            } }
        }
    }
    out
}

pub fn apply_patches(base: &[[f32; 4]], patches: &[ParamPatch], values: &[[f32; 4]]) -> Vec<[f32; 4]> {
    let mut cb = base.to_vec();
    for p in patches { if let (Some(r), Some(v)) = (cb.get_mut(p.reg), values.get(p.param)) { r[p.comp] = base[p.reg][p.comp] + p.scale * (v[p.src] - p.default); } }
    cb
}

/// Parameter names the constant buffer recipe of a permutation looks up.
pub fn recipe_param_names(perm: &str) -> Vec<String> {
    let names = std::cell::RefCell::new(vec![]);
    let rec = |n: &str, d: [f32; 4]| { names.borrow_mut().push(n.to_owned()); d };
    match perm { "head" => { genm::head_cb(&rec); } "hair" => { genm::hair_cb(&rec); } "body" => { genm::body_cb(&rec); } _ => {} }
    let mut v = names.into_inner();
    v.sort();
    v.dedup();
    v
}

/// One line per swatch: which of its colour names some character material parameter consumes (empty = none does: the swatch has no visible effect on that material).
pub fn swatch_report(swatch: &str, pairs: &[(String, [f32; 4])]) -> String {
    let all: Vec<String> = ["head", "hair", "body"].iter().flat_map(|p| recipe_param_names(p)).collect();
    let used: Vec<&str> = pairs.iter().map(|(n, _)| n.as_str()).filter(|n| all.iter().any(|a| a == n)).collect();
    format!("swatch {swatch}: {} colour pairs ({}); consumed by a head / hair / body material parameter: {:?}", pairs.len(), pairs.iter().map(|p| p.0.as_str()).collect::<Vec<_>>().join(", "), used)
}

fn load_fixed(src: &ClipSourceDir, path: &str, linear_sampler: bool) -> Result<FixedTex, String> {
    let t = loader::texture_export(src, path)?;
    if t.num_slices != 1 { return Err(format!("{path}: not a plain 2D texture")); }
    let mip = t.best_mip().ok_or_else(|| format!("{path}: no available mip"))?;
    let cooked = crate::br_character::CookedChain::of(&t).map(std::sync::Arc::new);
    let (width, height, rgba) = if cooked.is_some() && crate::br_character::cooked_only() { (t.mips[mip].width as usize, t.mips[mip].height as usize, Vec::new()) } else {
        let img = t.decode(mip, fn_texture::DecodeOptions::default()).map_err(|e| format!("{path}: {e}"))?;
        (img.width, img.height, img.to_rgba8())
    };
    Ok(FixedTex { tex: RgbaTexture { width, height, rgba, cooked }, srgb: t.srgb && !linear_sampler, address: [t.address_x.clone(), t.address_y.clone()], path: path.to_owned() })
}

/// The permutation that owns the shader map of `material`'s chain and the evaluated constant buffer. `overrides` (swatch colours) win over the instance chain, like the
/// parameters the engine sets on a dynamic instance. `Ok(None)` = no owner in the chain (not a character material permutation).
pub fn resolve_char_material(src: &ClipSourceDir, material: &str, overrides: &HashMap<String, [f32; 4]>) -> Result<Option<CharSection>, String> {
    let chain = chain_params(src, material)?;
    let Some((perm, owner)) = chain.packages.iter().find_map(|p| genm::PERMS.iter().find(|q| q.owner == p.as_str() && q.id != "eyeshadow").map(|q| (q.id, q.owner))) else { return Ok(None) };
    let profile_id = subsurface_profile_id(src, chain.subsurface_profile.as_deref())?;
    let lookup = |name: &str, d: [f32; 4]| -> [f32; 4] {
        if name == "__SubsurfaceProfile" { [profile_id as f32 / 255.; 4] }
        else if let Some(v) = overrides.get(name) { *v }
        else if let Some(v) = chain.vectors.get(name) { *v }
        else if let Some(s) = chain.scalars.get(name) { [*s; 4] }
        else { d }
    };
    let cb: Vec<[f32; 4]> = match perm { "head" => genm::head_cb(&lookup).to_vec(), "hair" => genm::hair_cb(&lookup).to_vec(), "body" => genm::body_cb(&lookup).to_vec(), o => return Err(format!("unknown permutation {o}")) };
    let noise = load_fixed(src, NOISE_PATH, false)?;
    let r = |i: usize| load_fixed(src, RES_IN_TEXTURES[i].0, RES_IN_TEXTURES[i].1);
    Ok(Some(CharSection { perm, owner: owner.to_owned(), cb, noise, res_in: [r(0)?, r(1)?, r(2)?], subsurface_profile: profile_id }))
}

/// The Eyeshadow material's constants (cooked defaults: nothing sets its parameters for a standing character) and fixed textures.
pub fn eyeshadow(src: &ClipSourceDir) -> Result<Eyeshadow, String> {
    let cb = genm::eyeshadow_cb(&|_, d| d).to_vec();
    let t = |i: usize| load_fixed(src, EYESHADOW_TEXTURES[i].0, EYESHADOW_TEXTURES[i].1);
    Ok(Eyeshadow { cb, tex: [t(0)?, t(1)?, t(2)?] })
}

/// Overrides of the part's swatches (name -> colour), skin swatch first then hair swatch.
pub fn swatch_overrides(src: &ClipSourceDir, defs: &[&PartDef], notes: &mut Vec<String>) -> HashMap<String, [f32; 4]> {
    let mut out = HashMap::new();
    let mut seen = vec![];
    for d in defs {
        for s in [&d.skin_swatch, &d.hair_swatch].into_iter().flatten() {
            if seen.contains(s) { continue; }
            seen.push(s.clone());
            match read_swatch(src, s) {
                Ok(pairs) => { notes.push(swatch_report(s, &pairs)); for (n, c) in pairs { out.insert(n, c); } }
                Err(e) => notes.push(format!("MISSING {s}: {e}")),
            }
        }
    }
    out
}

#[cfg(test)]
mod dissolve_tests {
    #[test] fn dissolve_parameters_patch_the_cooked_recipe_registers() {
        let ps = super::param_patches("head", &super::DISSOLVE_PARAMS);
        let at = |reg: usize, comp: usize| ps.iter().find(|p| p.reg == reg && p.comp == comp).copied();
        assert_eq!(at(25, 1).map(|p| (p.param, p.scale)), Some((3, 1.)));
        assert_eq!(at(25, 2).map(|p| (p.param, p.scale)), Some((3, 2.)));
        assert_eq!(at(24, 3).map(|p| p.param), Some(2));
        assert_eq!(at(18, 2).map(|p| (p.param, p.src)), Some((0, 2)));
        let base = super::recipe("head", &|_, d| d).unwrap();
        let mut v = [[0.; 4]; 5]; v[0] = [1., 2., 3., 1.]; v[1] = [0., 0., -1., 1.]; v[2] = [50.; 4]; v[3] = [0.25; 4]; v[4] = [1.; 4];
        let cb = super::apply_patches(&base, &ps, &v);
        assert_eq!((cb[25][1], cb[25][2], cb[24][3], cb[18][0]), (0.25, 0.5, 50., 1.));
        for perm in ["hair", "body"] { assert!(super::param_patches(perm, &super::DISSOLVE_PARAMS).iter().any(|p| p.param == 3)); }
    }
}
